75: /// Helper function to build dynamic SPA EnumFormat POD choice objects for multi-rate and multi-channel audio.
76: pub fn build_format_pod(
77:     rate_hz: u32,
78:     channels: u32,
79:     channel_positions: &[String],
80:     rate_mode: RateMode,
81:     allowed_rates: &[u32],
82: ) -> Result<Vec<u8>, PipeWireError> {
83:     let mut position_ids = Vec::with_capacity(channels as usize);
84:     for pos in channel_positions.iter().take(channels as usize) {
85:         position_ids.push(libspa::utils::Id(channel_position_to_spa(pos)));
86:     }
87:     while position_ids.len() < channels as usize {
88:         position_ids.push(libspa::utils::Id(libspa::sys::SPA_AUDIO_CHANNEL_UNKNOWN));
89:     }
90: 
91:     let rate_value = if rate_mode == RateMode::Dynamic && !allowed_rates.is_empty() {
92:         let (def, alternatives): (i32, Vec<i32>) = if allowed_rates.contains(&rate_hz) {
93:             (
94:                 rate_hz as i32,
95:                 allowed_rates
96:                     .iter()
97:                     .copied()
98:                     .filter(|&r| r != rate_hz)
99:                     .map(|r| r as i32)
100:                     .collect(),
101:             )
102:         } else {
103:             (
104:                 allowed_rates[0] as i32,
105:                 allowed_rates[1..].iter().map(|&r| r as i32).collect(),
106:             )
107:         };
108: 
109:         if alternatives.is_empty() {
110:             libspa::pod::Value::Int(def)
111:         } else {
112:             libspa::pod::Value::Choice(libspa::pod::ChoiceValue::Int(libspa::utils::Choice(
113:                 libspa::utils::ChoiceFlags::empty(),
114:                 libspa::utils::ChoiceEnum::Enum {
115:                     default: def,
116:                     alternatives,
117:                 },
118:             )))
119:         }
120:     } else {
121:         libspa::pod::Value::Int(rate_hz as i32)
122:     };
123: 
124:     let props = vec![
125:         libspa::pod::Property::new(
126:             libspa::sys::SPA_FORMAT_mediaType,
127:             libspa::pod::Value::Id(libspa::utils::Id(libspa::sys::SPA_MEDIA_TYPE_audio)),
128:         ),
129:         libspa::pod::Property::new(
130:             libspa::sys::SPA_FORMAT_mediaSubtype,
131:             libspa::pod::Value::Id(libspa::utils::Id(libspa::sys::SPA_MEDIA_SUBTYPE_raw)),
132:         ),
133:         libspa::pod::Property::new(
134:             libspa::sys::SPA_FORMAT_AUDIO_format,
135:             libspa::pod::Value::Id(libspa::utils::Id(AudioFormat::F32LE.as_raw())),
136:         ),
137:         libspa::pod::Property::new(libspa::sys::SPA_FORMAT_AUDIO_rate, rate_value),
138:         libspa::pod::Property::new(
139:             libspa::sys::SPA_FORMAT_AUDIO_channels,
140:             libspa::pod::Value::Int(channels as i32),
141:         ),
142:         libspa::pod::Property::new(
143:             libspa::sys::SPA_FORMAT_AUDIO_position,
144:             libspa::pod::Value::ValueArray(libspa::pod::ValueArray::Id(position_ids)),
145:         ),
146:     ];
147: 
148:     let obj = libspa::pod::Object {
149:         type_: libspa::utils::SpaTypes::ObjectParamFormat.as_raw(),
150:         id: libspa::param::ParamType::EnumFormat.as_raw(),
151:         properties: props,
152:     };
153: 
154:     libspa::pod::serialize::PodSerializer::serialize(
155:         std::io::Cursor::new(Vec::new()),
156:         &libspa::pod::Value::Object(obj),
