275: /// Computes a power-of-two PipeWire quantum (in frames) scaled to the stream rate (~21–23 ms).
276: pub fn quantum_frames_for_rate(rate_hz: u32) -> u32 {
277:     let mult = (rate_hz.max(44_100) / 44_100).next_power_of_two();
278:     1024_u32.saturating_mul(mult).clamp(1024, 65_536)
279: }
