339: /// Helper function to parse an SPA Format POD into audio format details.
340: pub fn parse_format_pod(bytes: &[u8]) -> Option<ParsedFormatInfo> {
341:     if bytes.len() < std::mem::size_of::<libspa::sys::spa_pod>() {
342:         return None;
343:     }
344:     let pod_ptr = bytes.as_ptr() as *const libspa::sys::spa_pod;
345:     unsafe {
346:         let mut media_type: u32 = 0;
347:         let mut media_subtype: u32 = 0;
348:         let res = libspa::sys::spa_format_parse(pod_ptr, &mut media_type, &mut media_subtype);
349:         if res < 0 || media_type != libspa::sys::SPA_MEDIA_TYPE_audio {
350:             return None;
351:         }
352: 
353:         let is_dsd = media_subtype == libspa::sys::SPA_MEDIA_SUBTYPE_dsd;
354:         let mut is_lsb = false;
355:         let mut interleave: i32 = 1; // default to interleaved
356:         let mut rate: Option<u32> = None;
357:         let mut channels: Option<u32> = None;
358: 
359:         let obj = pod_ptr as *const libspa::sys::spa_pod_object;
360:         let mut prop = libspa::sys::spa_pod_prop_first(&raw const (*obj).body);
361:         while libspa::sys::spa_pod_prop_is_inside(&raw const (*obj).body, (*pod_ptr).size, prop) {
362:             let key = (*prop).key;
363:             let val_ptr = &raw const (*prop).value;
364: 
365:             if key == libspa::sys::SPA_FORMAT_AUDIO_rate {
366:                 if (*val_ptr).type_ == libspa::sys::SPA_TYPE_Int {
367:                     let mut r: i32 = 0;
368:                     if libspa::sys::spa_pod_get_int(val_ptr, &mut r) >= 0 && r > 0 {
369:                         rate = Some(r as u32);
370:                     }
371:                 } else if libspa::sys::spa_pod_is_choice(val_ptr) > 0 {
372:                     let choice = val_ptr as *const libspa::sys::spa_pod_choice;
373:                     let body = &raw const (*choice).body;
374:                     let child_size = (*body).child.size as usize;
375:                     if child_size >= 4 {
376:                         let data_ptr = (body as *const u8)
377:                             .add(std::mem::size_of::<libspa::sys::spa_pod_choice_body>())
378:                             as *const i32;
379:                         let r = *data_ptr;
380:                         if r > 0 {
381:                             rate = Some(r as u32);
382:                         }
383:                     }
384:                 }
385:             } else if key == libspa::sys::SPA_FORMAT_AUDIO_channels {
386:                 if (*val_ptr).type_ == libspa::sys::SPA_TYPE_Int {
387:                     let mut c: i32 = 0;
388:                     if libspa::sys::spa_pod_get_int(val_ptr, &mut c) >= 0 && c > 0 {
389:                         channels = Some(c as u32);
390:                     }
391:                 } else if libspa::sys::spa_pod_is_choice(val_ptr) > 0 {
392:                     let choice = val_ptr as *const libspa::sys::spa_pod_choice;
393:                     let body = &raw const (*choice).body;
394:                     let child_size = (*body).child.size as usize;
395:                     if child_size >= 4 {
396:                         let data_ptr = (body as *const u8)
397:                             .add(std::mem::size_of::<libspa::sys::spa_pod_choice_body>())
398:                             as *const i32;
399:                         let c = *data_ptr;
400:                         if c > 0 {
401:                             channels = Some(c as u32);
402:                         }
403:                     }
404:                 }
405:             } else if key == libspa::sys::SPA_FORMAT_AUDIO_interleave {
406:                 if (*val_ptr).type_ == libspa::sys::SPA_TYPE_Int {
407:                     let mut iv: i32 = 0;
408:                     if libspa::sys::spa_pod_get_int(val_ptr, &mut iv) >= 0 {
409:                         interleave = iv;
410:                     }
411:                 } else if libspa::sys::spa_pod_is_choice(val_ptr) > 0 {
412:                     let choice = val_ptr as *const libspa::sys::spa_pod_choice;
413:                     let body = &raw const (*choice).body;
414:                     let child_size = (*body).child.size as usize;
415:                     if child_size >= 4 {
416:                         let data_ptr = (body as *const u8)
417:                             .add(std::mem::size_of::<libspa::sys::spa_pod_choice_body>())
418:                             as *const i32;
419:                         interleave = *data_ptr;
420:                     }
421:                 }
422:             } else if key == libspa::sys::SPA_FORMAT_AUDIO_bitorder {
423:                 if (*val_ptr).type_ == libspa::sys::SPA_TYPE_Id {
424:                     let mut b: u32 = 0;
425:                     if libspa::sys::spa_pod_get_id(val_ptr, &mut b) >= 0
426:                         && b == libspa::sys::SPA_PARAM_BITORDER_lsb
427:                     {
428:                         is_lsb = true;
429:                     }
430:                 } else if libspa::sys::spa_pod_is_choice(val_ptr) > 0 {
431:                     let choice = val_ptr as *const libspa::sys::spa_pod_choice;
432:                     let body = &raw const (*choice).body;
433:                     let child_size = (*body).child.size as usize;
434:                     if child_size >= 4 {
435:                         let data_ptr = (body as *const u8)
436:                             .add(std::mem::size_of::<libspa::sys::spa_pod_choice_body>())
437:                             as *const u32;
438:                         if *data_ptr == libspa::sys::SPA_PARAM_BITORDER_lsb {
439:                             is_lsb = true;
440:                         }
441:                     }
442:                 }
443:             }
444: 
445:             prop = libspa::sys::spa_pod_prop_next(prop);
446:         }
447: 
448:         if let Some(r) = rate {
449:             return Some(ParsedFormatInfo {
450:                 is_dsd,
451:                 is_lsb,
452:                 interleave,
453:                 rate: r,
454:                 channels: channels.unwrap_or(2),
455:             });
456:         }
457:     }
458:     None
459: }
