461: /// Helper function to parse SPA Props POD bytes into volume and mute updates.
462: pub fn parse_props_pod(bytes: &[u8]) -> Option<VolumeUpdate> {
463:     if let Ok((_, Value::Object(obj))) = PodDeserializer::deserialize_any_from(bytes) {
464:         let mut vol_pct: Option<f64> = None;
465:         let mut vol_db: Option<f64> = None;
466:         let mut is_muted: Option<bool> = None;
467: 
468:         let f_to_pct = |f: f32| -> f64 {
469:             if f <= 1e-6 {
470:                 0.0
471:             } else {
472:                 ((f as f64).cbrt() * 100.0).clamp(0.0, 150.0)
473:             }
474:         };
475: 
476:         for prop in obj.properties {
477:             if prop.key == libspa::sys::SPA_PROP_volume {
478:                 match prop.value {
479:                     Value::Float(f) => {
480:                         let pct = f_to_pct(f);
481:                         vol_pct = Some(pct);
482:                         vol_db = Some(audigma_dsp::alsamixer_percentage_to_db(
483:                             pct,
484:                             audigma_dsp::DEFAULT_SOFTWARE_MIN_DB,
485:                         ));
486:                     }
487:                     Value::Choice(ChoiceValue::Float(choice)) => {
488:                         let f = match choice.1 {
489:                             ChoiceEnum::None(v) => v,
490:                             ChoiceEnum::Range { default, .. } => default,
491:                             ChoiceEnum::Step { default, .. } => default,
492:                             ChoiceEnum::Enum { default, .. } => default,
493:                             ChoiceEnum::Flags { default, .. } => default,
494:                         };
495:                         let pct = f_to_pct(f);
496:                         vol_pct = Some(pct);
497:                         vol_db = Some(audigma_dsp::alsamixer_percentage_to_db(
498:                             pct,
499:                             audigma_dsp::DEFAULT_SOFTWARE_MIN_DB,
500:                         ));
501:                     }
502:                     _ => {}
503:                 }
504:             } else if prop.key == libspa::sys::SPA_PROP_mute {
505:                 match prop.value {
506:                     Value::Bool(b) => is_muted = Some(b),
507:                     Value::Choice(ChoiceValue::Bool(choice)) => {
508:                         let b = match choice.1 {
509:                             ChoiceEnum::None(v) => v,
510:                             ChoiceEnum::Range { default, .. } => default,
511:                             ChoiceEnum::Step { default, .. } => default,
512:                             ChoiceEnum::Enum { default, .. } => default,
513:                             ChoiceEnum::Flags { default, .. } => default,
514:                         };
515:                         is_muted = Some(b);
516:                     }
517:                     _ => {}
518:                 }
519:             } else if prop.key == libspa::sys::SPA_PROP_channelVolumes {
520:                 if let Value::ValueArray(ValueArray::Float(floats)) = prop.value {
521:                     if !floats.is_empty() {
522:                         let avg: f32 = floats.iter().sum::<f32>() / floats.len() as f32;
523:                         let pct = f_to_pct(avg);
524:                         vol_pct = Some(pct);
525:                         vol_db = Some(audigma_dsp::alsamixer_percentage_to_db(
526:                             pct,
527:                             audigma_dsp::DEFAULT_SOFTWARE_MIN_DB,
528:                         ));
529:                     }
530:                 }
531:             }
532:         }
533: 
534:         if vol_pct.is_some() || vol_db.is_some() || is_muted.is_some() {
535:             return Some(VolumeUpdate {
536:                 volume_db: vol_db,
537:                 volume_percent: vol_pct,
538:                 is_muted,
539:             });
540:         }
541:     }
542:     None
543: }
