545: /// PipeWire virtual audio sink node (`audigma_sink`).
546: ///
547: /// Desktop sound and audio players route into this virtual sink (`media.class = "Audio/Sink"`).
548: /// Incoming audio blocks are pushed into an SPSC ring buffer with monotonic generation tags.
549: pub struct PipeWireVirtualSink {
550:     info: AudioStreamInfo,
551:     _worker: Option<JoinHandle<()>>,
552:     consumer: Consumer<TaggedChunk>,
553:     current_chunk: Option<TaggedChunk>,
554:     read_offset: usize,
555:     generation: Arc<AtomicU64>,
556:     active_rate: Arc<AtomicU32>,
557:     pending_rate: Arc<AtomicU32>,
558:     is_dsd: Arc<AtomicBool>,
559:     is_lsb: Arc<AtomicBool>,
560:     interleave: Arc<AtomicI32>,
561:     active_dsd_bit_rate: Arc<AtomicU32>,
562:     pending_volume: Arc<Mutex<Option<VolumeUpdate>>>,
563:     running: Arc<AtomicBool>,
564:     dropped_chunks: Arc<AtomicU64>,
565:     processed_chunks: Arc<AtomicU64>,
566:     /// Queued input in native units: PCM frames for PCM, bytes-per-channel for DSD.
567:     /// Producer adds on push; consumer subtracts as native units are consumed.
568:     buffered_units: Arc<AtomicU64>,
569:     dsd_gain_db: f64,
570:     decimators: Vec<audigma_dsp::fir::HalfBandDecimationCascade>,
571:     dsd_scratch: Vec<Vec<u8>>,
572:     dsd_residue: Vec<Vec<u8>>,
573:     prerolled: bool,
574:     preroll_secs: f64,
575:     rt_consumer: Option<audigma_log::RtLogConsumer>,
576:     dropped_rt_events: Arc<AtomicU64>,
577:     decimation_recorder: Arc<audigma_log::DecimationErrorRecorder>,
578: }
579: 
580: impl PipeWireVirtualSink {
581:     /// Creates and binds a new virtual sink node in the PipeWire graph using an `InputConfig`.
582:     pub fn from_input_config(
583:         in_cfg: &InputConfig,
584:         default_rate_hz: u32,
585:         queue_chunks: usize,
586:     ) -> Result<Self, PipeWireError> {
587:         let node_name = in_cfg.node_name.as_deref().unwrap_or("audigma_sink");
588:         let channels = in_cfg.channels.unwrap_or(2) as u32;
589:         let positions = in_cfg.resolved_channel_positions();
590:         let rate_mode = in_cfg.rate_mode();
591:         let allowed_rates = in_cfg.resolved_allowed_rates();
592:         let rate_hz = in_cfg.rate_hz.map(|r| r.get()).unwrap_or(default_rate_hz);
593:         let allow_dsd = in_cfg.allow_dsd();
594:         let dsd_gain_db = in_cfg.dsd_gain_db();
595: 
596:         Self::new_internal(
597:             node_name,
598:             rate_hz,
599:             channels,
600:             positions,
601:             rate_mode,
602:             allowed_rates,
603:             allow_dsd,
604:             dsd_gain_db,
605:             queue_chunks,
606:         )
607:     }
608: 
609:     /// Creates and binds a new virtual sink node in the PipeWire graph with default stereo settings.
610:     pub fn new(
611:         node_name: &str,
612:         rate_hz: u32,
613:         channels: u32,
614:         queue_chunks: usize,
615:     ) -> Result<Self, PipeWireError> {
616:         let dummy_cfg = InputConfig {
617:             backend: audigma_settings::InputBackend::Pipewire,
618:             node_name: Some(node_name.to_string()),
619:             device: None,
620:             sample_format: None,
621:             rate_hz: PcmRateHz::new(rate_hz),
622:             channels: Some(channels as u8),
623:             channel_positions: None,
624:             rate_mode: None,
625:             allowed_rates: None,
626:             allow_dsd: None,
627:             dsd: None,
628:         };
629:         Self::from_input_config(&dummy_cfg, rate_hz, queue_chunks)
630:     }
631: 
632:     #[allow(clippy::too_many_arguments)]
633:     fn new_internal(
634:         node_name: &str,
635:         rate_hz: u32,
636:         channels: u32,
637:         channel_positions: Vec<String>,
638:         rate_mode: RateMode,
639:         allowed_rates: Vec<u32>,
640:         allow_dsd: bool,
641:         dsd_gain_db: f64,
642:         queue_chunks: usize,
643:     ) -> Result<Self, PipeWireError> {
644:         let desc = format!("Audigma Virtual Sink ({node_name})");
645:         let node_name_owned = node_name.to_string();
646: 
647:         let (mut producer, consumer) = RingBuffer::new(queue_chunks);
648:         let generation = Arc::new(AtomicU64::new(1));
649:         let active_rate = Arc::new(AtomicU32::new(rate_hz));
650:         let pending_rate = Arc::new(AtomicU32::new(0));
651:         let is_dsd = Arc::new(AtomicBool::new(false));
652:         let is_lsb = Arc::new(AtomicBool::new(false));
653:         let interleave = Arc::new(AtomicI32::new(1));
654:         let active_dsd_bit_rate = Arc::new(AtomicU32::new(0));
655:         let pending_volume = Arc::new(Mutex::new(None));
656:         let running = Arc::new(AtomicBool::new(true));
657:         let dropped_chunks = Arc::new(AtomicU64::new(0));
658:         let processed_chunks = Arc::new(AtomicU64::new(0));
659:         let buffered_units = Arc::new(AtomicU64::new(0));
660: 
661:         let (rt_producer, rt_consumer, dropped_rt_events) =
662:             audigma_log::rt_log_channel(audigma_log::DEFAULT_RT_QUEUE_CAPACITY);
663:         let rt_producer = Arc::new(Mutex::new(rt_producer));
664:         let rt_producer_cb = rt_producer.clone();
665:         let decimation_recorder = Arc::new(audigma_log::DecimationErrorRecorder::new());
666: 
667:         let gen_clone = generation.clone();
668:         let active_rate_cb = active_rate.clone();
669:         let pending_rate_cb = pending_rate.clone();
670:         let is_dsd_cb = is_dsd.clone();
671:         let is_lsb_cb = is_lsb.clone();
672:         let interleave_cb = interleave.clone();
673:         let active_dsd_rate_cb = active_dsd_bit_rate.clone();
674:         let pending_vol_cb = pending_volume.clone();
675:         let running_clone = running.clone();
676:         let dropped_chunks_cb = dropped_chunks.clone();
677:         let processed_chunks_cb = processed_chunks.clone();
678:         let buffered_units_cb = buffered_units.clone();
679: 
680:         let pos_str = channel_positions.join(",");
681:         let mut all_allowed_rates = allowed_rates.clone();
682:         if allow_dsd {
683:             for &dsd_byte_rate in &[352_800u32, 705_600, 1_411_200, 2_822_400] {
684:                 if !all_allowed_rates.contains(&dsd_byte_rate) {
685:                     all_allowed_rates.push(dsd_byte_rate);
686:                 }
687:             }
688:         }
689:         let allowed_rates_str = all_allowed_rates
690:             .iter()
691:             .map(|r| r.to_string())
692:             .collect::<Vec<_>>()
693:             .join(" ");
694: 
695:         let channel_positions_clone = channel_positions.clone();
696:         let allowed_rates_clone = allowed_rates.clone();
697: 
698:         let worker = std::thread::Builder::new()
699:             .name("audigma-pw-in".to_string())
700:             .spawn(move || {
701:                 pipewire::init();
702:                 let mainloop = match pipewire::main_loop::MainLoopBox::new(None) {
703:                     Ok(m) => m,
704:                     Err(_) => return,
705:                 };
706:                 let context = match pipewire::context::ContextBox::new(mainloop.loop_(), None) {
707:                     Ok(c) => c,
708:                     Err(_) => return,
709:                 };
710:                 let core = match context.connect(None) {
711:                     Ok(c) => c,
712:                     Err(_) => return,
713:                 };
714: 
715:                 let stream_name = node_name_owned.clone();
716:                 let mut stream_props = properties! {
717:                     *pipewire::keys::NODE_NAME => stream_name.as_str(),
718:                     *pipewire::keys::NODE_DESCRIPTION => desc.as_str(),
719:                     *pipewire::keys::MEDIA_CLASS => "Audio/Sink",
720:                     *pipewire::keys::MEDIA_TYPE => "Audio",
721:                     *pipewire::keys::MEDIA_ROLE => "Music",
722:                     *pipewire::keys::AUDIO_CHANNELS => format!("{channels}"),
723:                     "audio.position" => pos_str.as_str(),
724:                 };
725:                 if rate_mode == RateMode::Dynamic || allow_dsd {
726:                     stream_props.insert("audio.allowed-rates", format!("[ {allowed_rates_str} ]"));
727:                 }
728: 
729:                 let stream = match StreamBox::new(&core, &stream_name, stream_props) {
730:                     Ok(s) => s,
731:                     Err(_) => return,
732:                 };
733: 
734:                 let run_cb = running_clone.clone();
735:                 let is_dsd_process_cb = is_dsd_cb.clone();
736:                 let is_lsb_process_cb = is_lsb_cb.clone();
737:                 let interleave_process_cb = interleave_cb.clone();
738:                 let _listener = match stream
739:                     .add_local_listener_with_user_data(())
740:                     .param_changed(move |stream, _, id, param| {
741:                         let Some(param) = param else {
742:                             return;
743:                         };
744:                         if id == libspa::param::ParamType::Format.as_raw() {
745:                             let bytes = param.as_bytes();
746:                             let parsed = parse_format_pod(bytes);
747:                             let mut negotiated_stream_rate_and_stride: Option<(u32, u32)> = None;
748:                             if let Some(parsed) = parsed {
749:                                 is_dsd_cb.store(parsed.is_dsd, Ordering::SeqCst);
750:                                 is_lsb_cb.store(parsed.is_lsb, Ordering::SeqCst);
751:                                 interleave_cb.store(parsed.interleave, Ordering::SeqCst);
752:                                 if parsed.is_dsd {
753:                                     let bit_rate = parsed.rate * 8;
754:                                     active_dsd_rate_cb.store(bit_rate, Ordering::SeqCst);
755:                                     let dsd_rate_opt = DsdBitRateHz::new(bit_rate);
756:                                     let intermediate_rate = dsd_rate_opt
757:                                         .map(|r| {
758:                                             audigma_dsp::rates::select_dsd_intermediate_rate(
759:                                                 r, None, None,
760:                                             )
761:                                             .get()
762:                                         })
763:                                         .unwrap_or(176_400);
764: 
765:                                     if let Ok(mut p) = rt_producer_cb.try_lock() {
766:                                         let _ =
767:                                             p.try_push(audigma_log::RtLogEvent::FormatNegotiated {
768:                                                 is_dsd: true,
769:                                                 rate_hz: parsed.rate,
770:                                                 bit_rate_hz: bit_rate,
771:                                                 intermediate_rate_hz: intermediate_rate,
772:                                                 channels: parsed.channels as u8,
773:                                                 interleave: parsed.interleave,
774:                                             });
775:                                     }
776:                                     let stride = parsed.channels.max(1)
777:                                         * parsed.interleave.unsigned_abs().max(1);
778:                                     negotiated_stream_rate_and_stride = Some((parsed.rate, stride));
779:                                     let cur_active = active_rate_cb.load(Ordering::Relaxed);
780:                                     if cur_active != intermediate_rate {
781:                                         pending_rate_cb.store(intermediate_rate, Ordering::SeqCst);
782:                                     }
783:                                 } else {
784:                                     active_dsd_rate_cb.store(0, Ordering::SeqCst);
785:                                     if let Ok(mut p) = rt_producer_cb.try_lock() {
786:                                         let _ =
787:                                             p.try_push(audigma_log::RtLogEvent::FormatNegotiated {
788:                                                 is_dsd: false,
789:                                                 rate_hz: parsed.rate,
790:                                                 bit_rate_hz: parsed.rate,
791:                                                 intermediate_rate_hz: parsed.rate,
792:                                                 channels: parsed.channels as u8,
793:                                                 interleave: 1,
794:                                             });
795:                                     }
796:                                     let stride = parsed.channels.max(1) * 4;
797:                                     negotiated_stream_rate_and_stride = Some((parsed.rate, stride));
798:                                     let cur_active = active_rate_cb.load(Ordering::Relaxed);
799:                                     if cur_active != parsed.rate {
800:                                         pending_rate_cb.store(parsed.rate, Ordering::SeqCst);
801:                                     }
802:                                 }
803:                             } else {
804:                                 let mut info = AudioInfoRaw::new();
805:                                 if info.parse(param).is_ok() {
806:                                     is_dsd_cb.store(false, Ordering::SeqCst);
807:                                     is_lsb_cb.store(false, Ordering::SeqCst);
808:                                     active_dsd_rate_cb.store(0, Ordering::SeqCst);
809:                                     let negotiated_rate = info.rate();
810:                                     let negotiated_channels = info.channels();
811:                                     if let Ok(mut p) = rt_producer_cb.try_lock() {
812:                                         let _ =
813:                                             p.try_push(audigma_log::RtLogEvent::FormatNegotiated {
814:                                                 is_dsd: false,
815:                                                 rate_hz: negotiated_rate,
816:                                                 bit_rate_hz: negotiated_rate,
817:                                                 intermediate_rate_hz: negotiated_rate,
818:                                                 channels: negotiated_channels as u8,
819:                                                 interleave: 1,
820:                                             });
821:                                     }
822:                                     if negotiated_rate > 0 {
823:                                         let stride = negotiated_channels.max(1) * 4;
824:                                         negotiated_stream_rate_and_stride =
825:                                             Some((negotiated_rate, stride));
826:                                         let cur_active = active_rate_cb.load(Ordering::Relaxed);
827:                                         if cur_active != negotiated_rate {
828:                                             pending_rate_cb
829:                                                 .store(negotiated_rate, Ordering::SeqCst);
830:                                         }
831:                                     }
832:                                 }
833:                             }
834: 
835:                             if let Some((stream_rate, stride)) = negotiated_stream_rate_and_stride {
836:                                 let quantum_frames = quantum_frames_for_rate(stream_rate);
837:                                 if let Ok(buf_bytes) = build_buffers_pod(quantum_frames, stride) {
838:                                     if let Some(buf_pod) = Pod::from_bytes(&buf_bytes) {
839:                                         let mut params = [buf_pod];
840:                                         let _ = stream.update_params(&mut params);
841:                                     }
842:                                 }
843:                             }
844:                         } else if id == libspa::param::ParamType::Props.as_raw() {
845:                             let bytes = param.as_bytes();
846:                             if let Some(vol_update) = parse_props_pod(bytes) {
847:                                 if let Ok(mut p) = rt_producer_cb.try_lock() {
848:                                     let _ = p.try_push(audigma_log::RtLogEvent::VolumeEvent {
849:                                         volume_percent: vol_update.volume_percent.map(|v| v as f32),
850:                                         volume_db: vol_update.volume_db.map(|v| v as f32),
851:                                         muted: vol_update.is_muted,
852:                                     });
853:                                 }
854:                                 let mut pending = pending_vol_cb.lock().unwrap();
855:                                 let prev: VolumeUpdate = pending.unwrap_or_default();
856:                                 *pending = Some(VolumeUpdate {
857:                                     volume_db: vol_update.volume_db.or(prev.volume_db),
858:                                     volume_percent: vol_update
859:                                         .volume_percent
860:                                         .or(prev.volume_percent),
861:                                     is_muted: vol_update.is_muted.or(prev.is_muted),
862:                                 });
863:                             }
864:                         }
865:                     })
866:                     .process(move |stream, _| {
867:                         if !run_cb.load(Ordering::Relaxed) {
868:                             return;
869:                         }
870: 
871:                         if let Some(mut buffer) = stream.dequeue_buffer() {
872:                             let datas = buffer.datas_mut();
873:                             if datas.is_empty() {
874:                                 return;
875:                             }
876: 
877:                             processed_chunks_cb.fetch_add(1, Ordering::Relaxed);
878: 
879:                             let cur_gen = gen_clone.load(Ordering::Relaxed);
880:                             let n_ch = channels as usize;
881: 
882:                             if is_dsd_process_cb.load(Ordering::Relaxed) {
883:                                 // Native DSD stream (SPA audio/dsd)
884:                                 let reverse_bits = is_lsb_process_cb.load(Ordering::Relaxed);
885:                                 let iv = interleave_process_cb.load(Ordering::Relaxed);
886: 
887:                                 if iv == 0 || (datas.len() >= n_ch && n_ch > 1) {
888:                                     // Planar audio/dsd: each datas[c] holds channel c
889:                                     let channel_slices: Vec<&[u8]> = datas
890:                                         .iter_mut()
891:                                         .take(n_ch)
892:                                         .map(|data| {
