1691: impl PipeWirePcmOutput {
1692:     /// Creates and connects a new output stream into the PipeWire graph.
1693:     pub fn new(
1694:         stream_name: &str,
1695:         target_node: Option<&str>,
1696:         rate_hz: u32,
1697:         channels: u32,
1698:         queue_depth: usize,
1699:     ) -> Result<Self, PipeWireError> {
1700:         let (producer, mut consumer) = RingBuffer::<Vec<u8>>::new(queue_depth);
1701:         let running = Arc::new(AtomicBool::new(true));
1702:         let running_clone = running.clone();
1703:         let underruns = Arc::new(AtomicU64::new(0));
1704:         let overruns = Arc::new(AtomicU64::new(0));
1705:         let underruns_cb = underruns.clone();
1706:         let writer_thread: Arc<Mutex<Option<std::thread::Thread>>> = Arc::new(Mutex::new(None));
1707:         let writer_thread_cb = writer_thread.clone();
1708: 
1709:         let stream_name_owned = stream_name.to_string();
1710:         let target_node_owned = target_node.map(|s| s.to_string());
1711: 
1712:         let worker = std::thread::Builder::new()
1713:             .name("audigma-pw-out".to_string())
1714:             .spawn(move || {
1715:                 pipewire::init();
1716:                 let mainloop = match pipewire::main_loop::MainLoopBox::new(None) {
1717:                     Ok(m) => m,
1718:                     Err(_) => return,
1719:                 };
1720:                 let context = match pipewire::context::ContextBox::new(mainloop.loop_(), None) {
1721:                     Ok(c) => c,
1722:                     Err(_) => return,
1723:                 };
1724:                 let core = match context.connect(None) {
1725:                     Ok(c) => c,
1726:                     Err(_) => return,
1727:                 };
1728: 
1729:                 let mut props = properties! {
1730:                     *pipewire::keys::MEDIA_TYPE => "Audio",
1731:                     *pipewire::keys::MEDIA_CATEGORY => "Playback",
1732:                     *pipewire::keys::MEDIA_ROLE => "Music",
1733:                     *pipewire::keys::AUDIO_CHANNELS => format!("{channels}"),
1734:                     *pipewire::keys::NODE_LATENCY => format!("256/{rate_hz}"),
1735:                 };
1736: 
1737:                 if let Some(target) = &target_node_owned {
1738:                     props.insert("target.object", target.as_str());
1739:                 }
1740: 
1741:                 let stream = match StreamBox::new(&core, &stream_name_owned, props) {
1742:                     Ok(s) => s,
1743:                     Err(_) => return,
1744:                 };
1745: 
1746:                 let run_cb = running_clone.clone();
1747:                 // Retain any partially consumed queued chunk across PipeWire buffer callbacks.
1748:                 // The previous implementation popped one whole queued chunk per callback and
1749:                 // discarded the bytes that did not fit in the current PipeWire buffer, which
1750:                 // caused audible stuttering / rapid play-pause artefacts.
1751:                 let mut pending_buf: Option<Vec<u8>> = None;
1752:                 let mut pending_offset: usize = 0;
1753:                 let _listener = match stream
1754:                     .add_local_listener_with_user_data(())
1755:                     .process(move |stream, _| {
1756:                         if !run_cb.load(Ordering::Relaxed) {
1757:                             return;
1758:                         }
1759: 
1760:                         if let Some(mut buffer) = stream.dequeue_buffer() {
1761:                             let datas = buffer.datas_mut();
1762:                             if datas.is_empty() {
1763:                                 return;
1764:                             }
1765: 
1766:                             let data = &mut datas[0];
1767:                             let stride = (channels as usize) * std::mem::size_of::<f32>();
1768: 
1769:                             let mut bytes_written = 0usize;
1770:                             if let Some(slice) = data.data() {
1771:                                 let total = slice.len();
1772:                                 while bytes_written < total {
1773:                                     if pending_buf.is_none() {
1774:                                         match consumer.pop() {
1775:                                             Ok(buf) => {
1776:                                                 pending_buf = Some(buf);
1777:                                                 pending_offset = 0;
1778:                                                 if let Ok(guard) = writer_thread_cb.lock() {
1779:                                                     if let Some(t) = guard.as_ref() {
1780:                                                         t.unpark();
1781:                                                     }
1782:                                                 }
1783:                                             }
1784:                                             Err(_) => {
1785:                                                 underruns_cb.fetch_add(1, Ordering::Relaxed);
1786:                                                 break;
1787:                                             }
1788:                                         }
1789:                                     }
1790: 
1791:                                     let to_copy = {
1792:                                         let buf = pending_buf.as_ref().unwrap();
1793:                                         buf.len()
1794:                                             .saturating_sub(pending_offset)
1795:                                             .min(total - bytes_written)
1796:                                     };
1797: 
1798:                                     if to_copy > 0 {
1799:                                         let buf = pending_buf.as_ref().unwrap();
1800:                                         slice[bytes_written..bytes_written + to_copy]
1801:                                             .copy_from_slice(
1802:                                                 &buf[pending_offset..pending_offset + to_copy],
1803:                                             );
1804:                                         pending_offset += to_copy;
1805:                                         bytes_written += to_copy;
1806:                                     }
1807: 
1808:                                     let done = {
1809:                                         let buf = pending_buf.as_ref().unwrap();
1810:                                         pending_offset >= buf.len()
1811:                                     };
1812:                                     if done {
1813:                                         pending_buf = None;
1814:                                         pending_offset = 0;
1815:                                     }
1816:                                     if to_copy == 0 {
1817:                                         // Defensive: never spin forever on an empty queued chunk.
1818:                                         pending_buf = None;
1819:                                         pending_offset = 0;
1820:                                     }
1821:                                 }
1822: 
1823:                                 if bytes_written < total {
1824:                                     slice[bytes_written..].fill(0);
1825:                                     bytes_written = total;
1826:                                 }
1827:                             }
1828: 
1829:                             let chunk = data.chunk_mut();
1830:                             *chunk.offset_mut() = 0;
1831:                             *chunk.stride_mut() = stride as _;
1832:                             *chunk.size_mut() = bytes_written as _;
1833:                         }
1834:                     })
1835:                     .register()
1836:                 {
1837:                     Ok(l) => l,
1838:                     Err(_) => return,
1839:                 };
1840: 
1841:                 let pod_bytes = match build_format_pod(rate_hz, channels, &[], RateMode::Fixed, &[])
1842:                 {
1843:                     Ok(b) => b,
1844:                     Err(_) => return,
1845:                 };
1846:                 let mut params = [Pod::from_bytes(&pod_bytes).unwrap()];
1847: 
1848:                 if stream
1849:                     .connect(
1850:                         Direction::Output,
1851:                         None,
1852:                         StreamFlags::AUTOCONNECT
1853:                             | StreamFlags::MAP_BUFFERS
1854:                             | StreamFlags::RT_PROCESS,
1855:                         &mut params,
1856:                     )
1857:                     .is_err()
1858:                 {
1859:                     return;
1860:                 }
1861: 
1862:                 while running_clone.load(Ordering::Relaxed) {
1863:                     mainloop.loop_().iterate(pipewire::loop_::Timeout::Finite(
1864:                         std::time::Duration::from_millis(1),
1865:                     ));
1866:                 }
1867:             })
1868:             .map_err(|_e| PipeWireError::Native(pipewire::Error::NoMemory))?;
1869: 
1870:         Ok(Self {
1871:             _worker: Some(worker),
1872:             producer,
1873:             running,
1874:             underruns,
1875:             overruns,
1876:             writer_thread,
1877:         })
1878:     }
1879: }
