1882:     /// Number of output callbacks where the queued byte stream was empty.
1883:     pub fn underrun_count(&self) -> u64 {
1884:         self.underruns.load(Ordering::Relaxed)
1885:     }
1886: 
1887:     /// Number of writes rejected because the output queue was full.
1888:     pub fn overrun_count(&self) -> u64 {
1889:         self.overruns.load(Ordering::Relaxed)
1890:     }
1891: }
