1902: impl Write for PipeWirePcmOutput {
1903:     fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
1904:         if self.producer.is_full() {
1905:             // Register current thread handle so PipeWire consumer can unpark us
1906:             if let Ok(mut guard) = self.writer_thread.lock() {
1907:                 if guard.is_none() {
1908:                     *guard = Some(std::thread::current());
1909:                 }
1910:             }
1911: 
1912:             // Wait with backpressure (up to 20ms) for consumer to pop a slot
1913:             let start = std::time::Instant::now();
1914:             while self.producer.is_full() && start.elapsed() < std::time::Duration::from_millis(20)
1915:             {
1916:                 if !self.running.load(Ordering::Relaxed) {
1917:                     return Err(std::io::Error::new(
1918:                         std::io::ErrorKind::Interrupted,
1919:                         "PipeWire output stopped",
1920:                     ));
1921:                 }
1922:                 std::thread::park_timeout(std::time::Duration::from_micros(500));
1923:             }
1924:         }
1925: 
1926:         if self.producer.is_full() {
1927:             self.overruns.fetch_add(1, Ordering::Relaxed);
1928:             return Ok(buf.len());
1929:         }
1930: 
1931:         self.producer
1932:             .push(buf.to_vec())
1933:             .map(|_| buf.len())
1934:             .map_err(|_| std::io::Error::other("Failed to push to PipeWire queue"))
1935:     }
1936: 
1937:     fn flush(&mut self) -> std::io::Result<()> {
1938:         Ok(())
1939:     }
1940: }
1941: 
1942: impl AudioOutput for PipeWirePcmOutput {
1943:     fn xrun_count(&self) -> u64 {
1944:         self.underrun_count() + self.overrun_count()
1945:     }
1946: }

