88:     #[cfg(feature = "dbus")]
89:     let mut _reservation: Option<DeviceReservation> =
90:         if out_cfg.backend == OutputBackend::Alsa && out_cfg.reserve_device.unwrap_or(true) {
91:             let card_idx = out_cfg
92:                 .device
93:                 .as_deref()
94:                 .and_then(resolve_card_index)
95:                 .unwrap_or(0);
96: 
97:             match DeviceReservation::acquire(card_idx, "audigma", 100) {
98:                 Ok(res) => {
99:                     tracing::info!(
100:                         target: "audigma::daemon",
101:                         event = audigma_log::DEVICE_LOCK,
102:                         acquired = true,
103:                         card = card_idx,
104:                         name = res.well_known_name(),
105:                         "device lock acquired via D-Bus org.freedesktop.ReserveDevice1"
106:                     );
107:                     Some(res)
108:                 }
109:                 Err(e) => {
110:                     tracing::warn!(
111:                         target: "audigma::daemon",
112:                         event = audigma_log::DEVICE_LOCK,
113:                         acquired = false,
114:                         card = card_idx,
115:                         error = %e,
116:                         "failed to acquire D-Bus reservation"
117:                     );
118:                     None
119:                 }
120:             }
121:         } else {
122:             None
123:         };
124: 
125:     // Real-time thread priority
126:     #[cfg(feature = "dbus")]
127:     {
128:         match request_realtime_priority(10) {
129:             Ok(acq) => tracing::info!(
130:                 target: "audigma::daemon",
131:                 event = audigma_log::RT_PRIORITY,
132:                 acquired = true,
133:                 priority = 10,
134:                 method = %acq,
135:                 "real-time priority acquired"
136:             ),
137:             Err(e) => tracing::warn!(
138:                 target: "audigma::daemon",
139:                 event = audigma_log::RT_PRIORITY,
140:                 acquired = false,
141:                 priority = 10,
142:                 error = %e,
143:                 "real-time priority request skipped/fallback"
144:             ),
145:         }
146:     }
147: 
148:     // Set up Input Backend helper closure
149:     let out_buf_ms = out_cfg.buffer_ms.unwrap_or(40);
150:     let target_preroll_secs = (out_buf_ms as f64 / 1000.0 + 0.050).clamp(0.060, 0.500);
151: 
152:     let create_input_driver =
153:         |in_cfg: &audigma_settings::InputConfig| -> Result<Box<dyn AudioInput>, EngineError> {
154:             match in_cfg.backend {
155:                 #[cfg(feature = "pipewire")]
156:                 InputBackend::Pipewire => {
157:                     let mut sink =
158:                         PipeWireVirtualSink::from_input_config(in_cfg, input_rate.get(), 128)
159:                             .map_err(|e| EngineError::AudioBackend {
160:                                 backend: "pipewire",
161:                                 message: format!("failed to bind PipeWire virtual sink: {e}"),
162:                             })?;
163:                     sink.set_preroll_secs(target_preroll_secs);
164:                     Ok(Box::new(sink))
165:                 }
166:                 InputBackend::Alsa => Err(EngineError::AudioBackend {
167:                     backend: "alsa",
168:                     message: "ALSA live capture input not yet configured".to_string(),
169:                 }),
170:                 InputBackend::File | InputBackend::Stdio => Err(EngineError::InvalidTopology {
171:                     message: "File/Stdio backend is for offline mode; use 'audigma convert'"
172:                         .to_string(),
173:                 }),
174:                 #[cfg(not(feature = "pipewire"))]
175:                 InputBackend::Pipewire => Err(EngineError::AudioBackend {
176:                     backend: "pipewire",
177:                     message: "PipeWire feature is disabled in this build".to_string(),
178:                 }),
179:             }
180:         };
181: 
182:     let mut input_driver: Option<Box<dyn AudioInput>> = Some(create_input_driver(in_cfg)?);
183: 
184:     // Helper closure to create/open output backend driver
185:     let create_output_driver = |out_cfg: &audigma_settings::OutputConfig,
186:                                 target: &TargetRateSpec|
187:      -> Result<Box<dyn AudioOutput>, EngineError> {
188:         match out_cfg.backend {
189:             OutputBackend::Alsa => {
190:                 let alsa_config =
191:                     AlsaOutputConfig::from_settings(&settings, target).map_err(|e| {
192:                         EngineError::DeviceUnavailable {
193:                             device: settings
194:                                 .output
195:                                 .as_ref()
196:                                 .and_then(|o| o.device.clone())
197:                                 .unwrap_or_else(|| "default".to_string()),
198:                             reason: format!("failed to configure ALSA output: {e}"),
199:                         }
200:                     })?;
201:                 let target_device = alsa_config.device.clone();
202:                 let alsa_out = AlsaAudioOutput::open(alsa_config).map_err(|e| match e {
203:                     audigma_io::AlsaOutputError::DeviceDisconnected(reason) => {
204:                         EngineError::DeviceDisconnected(reason)
205:                     }
206:                     audigma_io::AlsaOutputError::Io(err) => EngineError::Io(err),
207:                     other => EngineError::DeviceUnavailable {
208:                         device: target_device,
209:                         reason: format!("failed to open ALSA output: {other}"),
210:                     },
211:                 })?;
212:                 Ok(Box::new(alsa_out))
213:             }
214:             #[cfg(feature = "pipewire")]
215:             OutputBackend::Pipewire => {
216:                 let target_node = out_cfg.target_node.as_deref();
217:                 let pw_rate = match target {
218:                     TargetRateSpec::Pcm { rate, .. } => rate.get(),
219:                     TargetRateSpec::Dsd { bit_rate } => {
220:                         return Err(EngineError::InvalidTopology {
221:                             message: format!(
222:                                 "PipeWire PCM output cannot carry DSD bit rate {bit_rate}"
223:                             ),
224:                         });
225:                     }
226:                 };
227:                 // Calculate queue depth based on output.buffer_ms and sample rate (assuming ~64 frames/tile).
228:                 // Clamp between 64 and 256 tiles (~20ms to 85ms at 192kHz) to keep latency tight.
229:                 let tiles_per_sec = (pw_rate as f64 / 64.0).ceil() as usize;
230:                 let queue_depth = ((tiles_per_sec * out_buf_ms as usize) / 1000).clamp(64, 256);
231:                 let pw_out = PipeWirePcmOutput::new(
232:                     "audigma_pcm_out",
233:                     target_node,
234:                     pw_rate,
235:                     channels as u32,
236:                     queue_depth,
237:                 )
238:                 .map_err(|e| EngineError::AudioBackend {
239:                     backend: "pipewire",
240:                     message: format!("failed to initialize PipeWire output: {e}"),
241:                 })?;
242:                 Ok(Box::new(pw_out))
243:             }
244:             #[cfg(not(feature = "pipewire"))]
245:             OutputBackend::Pipewire => Err(EngineError::AudioBackend {
246:                 backend: "pipewire",
247:                 message: "PipeWire feature is disabled in this build".to_string(),
248:             }),
249:             OutputBackend::File | OutputBackend::Stdio => Err(EngineError::InvalidTopology {
250:                 message: "File/Stdio backend is for offline mode; use 'audigma convert'"
251:                     .to_string(),
252:             }),
253:         }
254:     };
255: 
256:     let (out_fmt, out_rate_hz) = match target_spec {
257:         TargetRateSpec::Dsd { bit_rate } => (DaemonOutputFormat::Dsd, bit_rate.get()),
258:         TargetRateSpec::Pcm { rate, .. } => (DaemonOutputFormat::Pcm, rate.get()),
259:     };
260: 
261:     let control = DaemonControlHandle::new(
262:         input_rate.get(),
263:         out_fmt,
264:         out_rate_hz,
265:         match plan.dsp_config.preset {
266:             audigma_dsp::config::FilterPreset::Balanced => "balanced",
267:             audigma_dsp::config::FilterPreset::Reference => "reference",
268:             audigma_dsp::config::FilterPreset::LowLatency => "low-latency",
269:         },
270:         plan.dsp_config.preamp_db,
271:     );
272: 
273:     // Install SIGINT / SIGTERM handler to stop daemon cleanly (§9, §13.12)
274:     DAEMON_RUNNING_PTR.store(Arc::as_ptr(&control.running) as *mut _, Ordering::SeqCst);
275:     unsafe {
276:         libc::signal(
277:             libc::SIGINT,
278:             sigint_sigterm_handler as *const () as libc::sighandler_t,
279:         );
280:         libc::signal(
281:             libc::SIGTERM,
282:             sigint_sigterm_handler as *const () as libc::sighandler_t,
283:         );
284:     }
285: 
286:     // Start Unix Control Socket
287:     let socket_path = default_socket_path();
288:     let _server =
289:         ControlServer::start(socket_path.clone(), control.clone()).map_err(CliError::Ipc)?;
290:     tracing::info!(
291:         target: "audigma::ipc",
292:         event = audigma_log::CONTROL_SOCKET_BOUND,
293:         path = %socket_path.display(),
294:         "control socket bound"
295:     );
296: 
297:     // Real-time thread priority hook for channel workers
298:     #[cfg(feature = "dbus")]
299:     let worker_rt_hook: Option<Arc<dyn Fn(usize) + Send + Sync>> =
300:         Some(Arc::new(|ch: usize| match request_realtime_priority(10) {
301:             Ok(acq) => tracing::info!(
302:                 target: "audigma::daemon",
303:                 event = audigma_log::RT_PRIORITY,
304:                 worker = ch,
305:                 acquired = true,
306:                 priority = 10,
307:                 method = %acq,
308:                 "worker acquired real-time priority"
309:             ),
310:             Err(e) => tracing::warn!(
311:                 target: "audigma::daemon",
312:                 event = audigma_log::RT_PRIORITY,
313:                 worker = ch,
314:                 acquired = false,
315:                 priority = 10,
316:                 error = %e,
317:                 "worker real-time priority request skipped/fallback"
318:             ),
319:         }));
320:     #[cfg(not(feature = "dbus"))]
321:     let worker_rt_hook: Option<Arc<dyn Fn(usize) + Send + Sync>> = None;
322: 
323:     // Set up and spawn audigma-rt-log drainer thread (§8.4)
324:     let mut rt_drainer = audigma_log::RtLogDrainer::new();
325:     if let Some(ref mut input) = input_driver {
326:         if let Some(consumer) = input.take_rt_consumer() {
327:             let dropped = input
328:                 .dropped_rt_events()
329:                 .unwrap_or_else(|| Arc::new(std::sync::atomic::AtomicU64::new(0)));
330:             rt_drainer.add_channel(consumer, dropped);
331:         }
332:         if let Some(recorder) = input.decimation_recorder() {
333:             rt_drainer.add_decimation_recorder(recorder);
334:         }
335:     }
336:     let mut _rt_drainer_handle = rt_drainer.spawn();
337: 
338:     // Prepare and Run Live Pipeline
339:     let mut pipeline =
340:         LivePipeline::prepare_with_hook(settings.clone(), input_rate, worker_rt_hook.clone())?;
341:     let mut current_input_rate = input_rate;
342:     let mut current_target_spec = target_spec;
343:     let mut generation: u64 = 1;
344: 
345:     let target_device = out_cfg
346:         .device
347:         .clone()
348:         .unwrap_or_else(|| "default".to_string());
349:     let custom_mixer_control = out_cfg.mixer_control();
350:     let vol_control_mode = out_cfg.volume_control();
351:     let device_wait_ms = out_cfg.device_wait_ms();
352:     let keep_audio_sink_ms = out_cfg.keep_audio_sink_ms();
353: 
354:     let mut hw_mixer: Option<AlsaHardwareMixer> = if out_cfg.backend == OutputBackend::Alsa {
355:         match AlsaHardwareMixer::open(&target_device, custom_mixer_control) {
356:             Ok(m) => {
357:                 tracing::info!(
358:                     target: "audigma::alsa",
359:                     event = "hardware_mixer_bound",
360:                     control = m.element_name(),
361:                     "bound to ALSA mixer control"
362:                 );
363:                 Some(m)
364:             }
365:             Err(e) => {
366:                 tracing::info!(
367:                     target: "audigma::alsa",
368:                     event = audigma_log::HARDWARE_MIXER_UNAVAILABLE,
369:                     device = %target_device,
370:                     error = %e,
371:                     "hardware mixer unavailable"
372:                 );
373:                 None
374:             }
375:         }
376:     } else {
377:         None
378:     };
379: 
380:     let active_vol_mode = match vol_control_mode {
381:         audigma_settings::VolumeControlMode::HardwareSoftwareFallback => {
382:             if hw_mixer.is_some() {
383:                 DaemonVolumeMode::Hardware
384:             } else {
385:                 DaemonVolumeMode::Software
386:             }
387:         }
388:         audigma_settings::VolumeControlMode::Hardware => {
389:             if hw_mixer.is_none() {
390:                 tracing::warn!(
391:                     target: "audigma::daemon",
392:                     event = audigma_log::VOLUME_MODE,
393:                     "hardware volume requested but no mixer element found; digital gain locked at 0 dBFS"
394:                 );
395:             }
396:             DaemonVolumeMode::Hardware
397:         }
398:         audigma_settings::VolumeControlMode::Software => DaemonVolumeMode::Software,
399:         audigma_settings::VolumeControlMode::None => DaemonVolumeMode::None,
400:     };
401:     control.set_volume_mode(active_vol_mode);
402:     tracing::info!(
403:         target: "audigma::daemon",
404:         event = audigma_log::VOLUME_MODE,
405:         active = %active_vol_mode,
406:         configured = ?vol_control_mode,
407:         "volume mode configured"
408:     );
409: 
410:     let mut current_output: Option<Box<dyn AudioOutput>> = None;
411: 
412:     // Resilient daemon loop
413:     while control.is_running() {
414:         // Step 1: Ensure output device is connected and opened
415:         if current_output.is_none() {
416:             if out_cfg.backend == OutputBackend::Alsa && !is_alsa_device_present(&target_device) {
417:                 if device_wait_ms == 0 {
418:                     return Err(EngineError::DeviceDisconnected(format!(
419:                         "target ALSA device '{target_device}' is not present at startup"
420:                     ))
421:                     .into());
422:                 }
423: 
424:                 tracing::info!(
425:                     target: "audigma::daemon",
426:                     event = audigma_log::DEVICE_WAIT_TICK,
427:                     device = %target_device,
428:                     elapsed_s = 0,
429:                     sink_active = true,
430:                     device_wait_ms,
431:                     keep_audio_sink_ms,
432:                     "waiting for output device"
433:                 );
434:                 control.set_state(DaemonState::WaitingForDevice);
435:                 control.set_disconnect_info(Some(target_device.clone()), Some(0));
436: 
437:                 let wait_start = Instant::now();
438:                 let mut sink_dropped = false;
439:                 let mut last_log_secs = 0u64;
440: 
441:                 while control.is_running() {
442:                     let elapsed_ms = wait_start.elapsed().as_millis() as u64;
443:                     let elapsed_secs = elapsed_ms / 1000;
444:                     control.set_disconnect_info(Some(target_device.clone()), Some(elapsed_ms));
445: 
446:                     // Periodic waiting heartbeat every 5 seconds
447:                     if elapsed_secs >= last_log_secs + 5 {
448:                         last_log_secs = elapsed_secs;
449:                         tracing::info!(
450:                             target: "audigma::daemon",
451:                             event = audigma_log::DEVICE_WAIT_TICK,
452:                             device = %target_device,
453:                             elapsed_s = elapsed_secs,
454:                             sink_active = !sink_dropped,
455:                             "still waiting for output device"
456:                         );
457:                     }
458: 
459:                     // Check device_wait_ms timeout
460:                     if device_wait_ms > 0 && elapsed_ms >= device_wait_ms as u64 {
461:                         tracing::error!(
462:                             target: "audigma::daemon",
463:                             event = "device_wait_timeout",
464:                             device = %target_device,
465:                             elapsed_ms,
466:                             timeout_ms = device_wait_ms,
467:                             "device_wait_ms timeout reached; exiting"
468:                         );
469:                         return Err(EngineError::DeviceDisconnected(format!(
470:                             "timed out waiting for device '{target_device}' after {device_wait_ms} ms"
471:                         )).into());
472:                     }
473: 
474:                     // Check keep_audio_sink_ms grace period
475:                     if !sink_dropped
476:                         && keep_audio_sink_ms >= 0
477:                         && elapsed_ms >= keep_audio_sink_ms as u64
478:                     {
479:                         tracing::warn!(
480:                             target: "audigma::daemon",
481:                             event = "keep_audio_sink_expired",
482:                             device = %target_device,
483:                             keep_audio_sink_ms,
484:                             "keep_audio_sink_ms expired; unregistering virtual sink from PipeWire graph"
485:                         );
486:                         input_driver = None; // Drop virtual sink to unregister from PipeWire
487:                         sink_dropped = true;
488:                     }
489: 
490:                     // If virtual sink is still registered, bit-bucket drain incoming frames pacingly
491:                     if let Some(ref mut input) = input_driver {
492:                         let mut drain_left = [0.0; 256];
493:                         let mut drain_right = [0.0; 256];
494:                         let _ = input.read_stereo(&mut drain_left, &mut drain_right);
495:                     }
496: 
497:                     // Wait for inotify event or slice
498:                     if wait_for_alsa_device(&target_device, 200, &control.running).unwrap_or(false)
499:                     {
500:                         tracing::info!(
501:                             target: "audigma::daemon",
502:                             event = "hotplug_event_detected",
503:                             device = %target_device,
504:                             "hotplug event detected: output device is present"
505:                         );
506:                         break;
507:                     }
508:                 }
509: 
510:                 if !control.is_running() {
511:                     break;
512:                 }
513: 
514:                 // Re-register input virtual sink if it was dropped
515:                 if input_driver.is_none() {
516:                     tracing::info!(
517:                         target: "audigma::daemon",
518:                         event = "input_sink_rebind",
519:                         "re-registering virtual sink in PipeWire graph"
520:                     );
521:                     input_driver = Some(create_input_driver(in_cfg)?);
522:                 }
523: 
524:                 // Re-acquire D-Bus device reservation if needed
525:                 #[cfg(feature = "dbus")]
526:                 if out_cfg.reserve_device.unwrap_or(true) {
527:                     let card_idx = resolve_card_index(&target_device).unwrap_or(0);
528:                     match DeviceReservation::acquire(card_idx, "audigma", 100) {
529:                         Ok(res) => {
530:                             tracing::info!(
531:                                 target: "audigma::daemon",
532:                                 event = audigma_log::DEVICE_LOCK,
533:                                 acquired = true,
534:                                 card = card_idx,
535:                                 name = res.well_known_name(),
536:                                 "re-acquired D-Bus device reservation"
537:                             );
538:                             _reservation = Some(res);
539:                         }
540:                         Err(e) => {
541:                             tracing::warn!(
542:                                 target: "audigma::daemon",
543:                                 event = audigma_log::DEVICE_LOCK,
544:                                 acquired = false,
545:                                 card = card_idx,
546:                                 error = %e,
547:                                 "failed to re-acquire D-Bus reservation"
548:                             );
549:                         }
550:                     }
551:                 }
552:             }
553: 
554:             // Open output device
555:             match create_output_driver(out_cfg, &current_target_spec) {
556:                 Ok(out) => {
557:                     tracing::info!(
558:                         target: "audigma::alsa",
559:                         event = audigma_log::OUTPUT_DEVICE_OPENED,
560:                         device = %target_device,
561:                         backend = ?out_cfg.backend,
562:                         "opened output device; resuming streaming"
563:                     );
564:                     current_output = Some(out);
565:                     control.set_disconnect_info(None, None);
566: 
567:                     // Re-bind ALSA hardware mixer if applicable
568:                     if out_cfg.backend == OutputBackend::Alsa {
569:                         hw_mixer =
570:                             match AlsaHardwareMixer::open(&target_device, custom_mixer_control) {
571:                                 Ok(mut m) => {
572:                                     tracing::info!(
573:                                         target: "audigma::alsa",
574:                                         event = "hardware_mixer_rebound",
575:                                         control = m.element_name(),
576:                                         "re-bound ALSA hardware mixer"
577:                                     );
578:                                     let cur_vol = control.get_volume();
579:                                     let is_muted = control.is_muted();
580:                                     let _ = m.set_volume_db(cur_vol);
581:                                     let _ = m.set_mute(is_muted);
582:                                     Some(m)
583:                                 }
584:                                 Err(_) => None,
585:                             };
586:                     }
587:                 }
588:                 Err(e) => {
589:                     tracing::warn!(
590:                         target: "audigma::alsa",
591:                         event = "output_open_retry",
592:                         device = %target_device,
593:                         error = %e,
594:                         "failed to open output device; retrying in 500ms"
595:                     );
596:                     std::thread::sleep(Duration::from_millis(500));
597:                     continue;
598:                 }
599:             }
600:         }
601: 
602:         // Ensure input driver is active
603:         if input_driver.is_none() {
604:             input_driver = Some(create_input_driver(in_cfg)?);
605:         }
606: 
607:         let input = input_driver.as_mut().unwrap();
608:         let output = current_output.as_mut().unwrap();
609: 
610:         // Run streaming loop
611:         match pipeline.run_streaming_with_bridge(
612:             &mut **input,
613:             &mut **output,
614:             control.clone(),
615:             hw_mixer
616:                 .as_mut()
617:                 .map(|m| m as &mut dyn audigma_engine::HardwareVolumeBridge),
618:         ) {
619:             Ok(StreamExitReason::Stopped) => break,
620:             Ok(StreamExitReason::RateChanged {
621:                 new_rate,
622:                 channels: _,
623:             }) => {
624:                 let new_plan = settings.explain_for_input_rate(new_rate)?;
625:                 let new_target_spec = new_plan.stream_spec.target;
626: 
627:                 let need_reopen_output = match (current_target_spec, new_target_spec) {
628:                     (
629:                         TargetRateSpec::Dsd { bit_rate: old_br },
630:                         TargetRateSpec::Dsd { bit_rate: new_br },
631:                     ) => old_br != new_br,
632:                     (
633:                         TargetRateSpec::Pcm { rate: old_r, .. },
634:                         TargetRateSpec::Pcm { rate: new_r, .. },
635:                     ) => old_r != new_r,
636:                     _ => true,
637:                 };
638: 
639:                 let (output_format, output_rate_hz) = match new_target_spec {
640:                     TargetRateSpec::Dsd { bit_rate } => (DaemonOutputFormat::Dsd, bit_rate.get()),
641:                     TargetRateSpec::Pcm { rate, .. } => (DaemonOutputFormat::Pcm, rate.get()),
642:                 };
643: 
644:                 tracing::info!(
645:                     target: "audigma::clock",
646:                     event = audigma_log::RATE_SWITCH,
647:                     from_hz = current_input_rate.get(),
648:                     to_hz = new_rate.get(),
649:                     generation = generation + 1,
650:                     reopened_output = need_reopen_output,
651:                     target_format = ?output_format,
652:                     "dynamic sample rate switch detected"
653:                 );
654:                 current_input_rate = new_rate;
655: 
656:                 if need_reopen_output {
657:                     tracing::info!(
658:                         target: "audigma::output",
659:                         event = audigma_log::OUTPUT_REOPENED,
660:                         device = %target_device,
661:                         reason = "rate_switch",
662:                         "re-opening output stream for new target rate"
663:                     );
664:                     current_output = None;
665:                 }
666: 
667:                 // Re-prepare the LivePipeline for the new input rate
668:                 pipeline = LivePipeline::prepare_with_hook(
669:                     settings.clone(),
670:                     new_rate,
671:                     worker_rt_hook.clone(),
672:                 )?;
673:                 current_target_spec = new_target_spec;
674: 
675:                 // Bump generation and update active rate on virtual sink
676:                 generation += 1;
677:                 control.generation.store(generation, Ordering::SeqCst);
678:                 control.inc_rate_switch();
679:                 input.set_generation(generation);
680:                 input.set_active_rate(new_rate);
681:                 input.set_preroll_secs(target_preroll_secs);
682: 
683:                 // Update telemetry
684:                 control.set_stream_config(new_rate.get(), output_format, output_rate_hz);
685: 
686:                 continue;
687:             }
