10: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
11: pub struct PipelineTopology {
12:     /// Input PCM rate (or decimated intermediate PCM rate if input was DSD).
13:     pub input_rate: PcmRateHz,
14:     /// Intermediate baseband rate after any rational SRC and before the power-of-two half-band cascade.
15:     pub intermediate_rate: PcmRateHz,
16:     /// Number of 2x power-of-two half-band FIR upsampling stages.
17:     pub cascade_stages: usize,
18:     /// Effective rate multiplier of the half-band cascade (`1 << cascade_stages`).
19:     pub rate_multiplier: usize,
20:     /// Whether polyphase rational SRC is required between input rate and intermediate rate.
21:     pub requires_rational_src: bool,
22:     /// Resolved target output rate specification.
23:     pub target_spec: TargetRateSpec,
24: }
25: 
26: impl PipelineTopology {
27:     /// Resolves intermediate baseband rate and power-of-two half-band stages.
28:     pub fn resolve(
29:         input_rate: PcmRateHz,
30:         target_spec: TargetRateSpec,
31:     ) -> Result<Self, EngineError> {
32:         let (intermediate_rate, stages) = match target_spec {
33:             TargetRateSpec::Dsd { bit_rate } => {
34:                 let dsd_family = bit_rate.rate_family();
35:                 let in_family = input_rate.rate_family();
36:                 if in_family == dsd_family {
37:                     if bit_rate.get() >= input_rate.get() {
38:                         let mult = bit_rate.get() / input_rate.get();
39:                         let stages = (mult as f64).log2().round() as usize;
40:                         (input_rate, stages)
41:                     } else {
42:                         return Err(EngineError::InvalidTopology {
43:                             message: format!(
44:                                 "input rate {input_rate} exceeds DSD bit rate {bit_rate}"
45:                             ),
46:                         });
47:                     }
48:                 } else {
49:                     // Cross-family conversion (e.g. 192k 48-family -> 44.1-family DSD):
50:                     // Resample at matched tier (192k -> 176.4k) to preserve ultrasonic content,
51:                     // then upsample via power-of-two half-band FIR stages to target DSD bit rate.
52:                     let matched_tier_rate = input_rate
53:                         .corresponding_rate_in_family(dsd_family)
54:                         .filter(|r| bit_rate.get() >= r.get())
55:                         .or_else(|| dsd_family.base_pcm_rate())
56:                         .ok_or_else(|| EngineError::InvalidTopology {
57:                             message: format!("invalid rate family for DSD bit rate {bit_rate}"),
58:                         })?;
59:                     let mult = bit_rate.get() / matched_tier_rate.get();
60:                     let stages = (mult as f64).log2().round() as usize;
61:                     (matched_tier_rate, stages)
62:                 }
63:             }
64:             TargetRateSpec::Pcm { rate, .. } => {
65:                 let target_family = rate.rate_family();
66:                 let in_family = input_rate.rate_family();
67:                 if in_family == target_family {
68:                     let mult = rate.get() / input_rate.get();
69:                     let stages = if mult >= 1 {
70:                         (mult as f64).log2().round() as usize
71:                     } else {
72:                         0
73:                     };
74:                     (input_rate, stages)
75:                 } else {
76:                     // Cross-family PCM conversion:
77:                     // If target rate allows, resample at matched tier first, then power-of-two stages
78:                     let matched_tier_rate = input_rate
79:                         .corresponding_rate_in_family(target_family)
80:                         .filter(|r| rate.get() >= r.get())
81:                         .or_else(|| target_family.base_pcm_rate())
82:                         .ok_or_else(|| EngineError::InvalidTopology {
83:                             message: format!("invalid target rate family for {rate}"),
84:                         })?;
85:                     let mult = rate.get() / matched_tier_rate.get();
86:                     let stages = if mult >= 1 {
87:                         (mult as f64).log2().round() as usize
88:                     } else {
89:                         0
90:                     };
91:                     (matched_tier_rate, stages)
92:                 }
93:             }
94:         };
95: 
96:         let rate_multiplier = 1usize << stages;
97:         let requires_rational_src = input_rate != intermediate_rate;
98: 
99:         Ok(Self {
100:             input_rate,
101:             intermediate_rate,
102:             cascade_stages: stages,
103:             rate_multiplier,
104:             requires_rational_src,
105:             target_spec,
106:         })
107:     }
