351: /// Selects the optimal intermediate PCM rate for DSD decimation remodulation
352: /// according to the formula in `Design.md §1.6`:
353: /// `Rate_intermediate = min(Rate_in_useful, Rate_out_useful, max_intermediate_rate_hz)`.
354: pub fn select_dsd_intermediate_rate(
355:     in_rate: DsdBitRateHz,
356:     target_spec: Option<&TargetRateSpec>,
357:     max_intermediate_rate_hz: Option<PcmRateHz>,
358: ) -> PcmRateHz {
359:     let in_family = in_rate.rate_family();
360:     let base_in_rate = in_family.base_pcm_rate().unwrap_or(PcmRateHz::PCM_44100);
361: 
362:     // in_useful: 176.4k/192k for DSD64, 352.8k/384k for DSD128+
363:     let in_useful = match in_rate.dsd_multiplier() {
364:         Some(DsdMultiplier::Dsd64) => base_in_rate.0 * 4, // 176.4k / 192k
365:         _ => base_in_rate.0 * 8,                          // 352.8k / 384k (DXD)
366:     };
367: 
368:     // out_useful: target rate if PCM, or corresponding DSD useful baseband
369:     let out_useful = match target_spec {
370:         Some(TargetRateSpec::Pcm { rate, .. }) => rate.get(),
371:         Some(TargetRateSpec::Dsd { bit_rate }) => {
372:             let out_base = bit_rate
373:                 .rate_family()
374:                 .base_pcm_rate()
375:                 .unwrap_or(PcmRateHz::PCM_44100);
376:             match bit_rate.dsd_multiplier() {
377:                 Some(DsdMultiplier::Dsd64) => out_base.0 * 4,
378:                 _ => out_base.0 * 8,
379:             }
380:         }
381:         None => in_useful,
382:     };
383: 
384:     // max_intermediate: user limit or default 352.8k / 384k
385:     let default_max = base_in_rate.0 * 8;
386:     let max_intermediate = max_intermediate_rate_hz
387:         .map(|r| r.get())
388:         .unwrap_or(default_max);
389: 
390:     // Apply min formula: min(in_useful, out_useful, max_intermediate)
391:     let selected_hz = in_useful.min(out_useful).min(max_intermediate);
392: 
393:     // Candidate power-of-two rates in in_family: 4x (176.4k/192k) or 8x (352.8k/384k)
394:     let rate_4x = base_in_rate.0 * 4;
395:     let rate_8x = base_in_rate.0 * 8;
396: 
397:     let final_hz = if selected_hz <= rate_4x {
398:         rate_4x
399:     } else {
400:         rate_8x
401:     };
402: 
403:     PcmRateHz::new(final_hz).unwrap_or(PcmRateHz::PCM_352800)
